INSERT INTO `cbt_exams` (`id`, `code`, `title`, `subject`, `academic_year`, `semester`, `duration_minutes`, `passing_grade`, `total_questions`, `classes_allowed`, `randomize_questions`, `randomize_options`, `max_violations_allowed`, `status`, `token`, `author_id`, `author_name`, `author_username`, `start_time`, `end_time`, `exam_date`, `exam_start_time`, `exam_end_time`, `questions_json`) VALUES
('exm-001', 'AM-FIKIH-MTS-2026', 'Asesmen Madrasah (AM): Fikih & Ibadah Terapan MTs', 'Fikih MTs', '2026/2027', 'Genap', 45, 75, 10, 'cls-7a,cls-7b,cls-8a,cls-8b,cls-9a', 1, 1, 3, 'active', 'FIQ789', 'usr-teacher-1', 'Siti Fatimah, S.Pd.I', 'guru', '2026-10-19T07:30:00Z', '2026-10-19T09:00:00Z', '2026-10-19', '07:30', '09:00', '[{"id":"q-1","number":1,"type":"multiple_choice","text":"Air yang suci tetapi tidak dapat digunakan untuk menyucikan benda lain (suci tidak menyucikan) menurut kaidah Fikih Thaharah adalah...","options":[{"id":"opt-1-a","text":"Air kelapa murni dan air teh manis","isCorrect":true},{"id":"opt-1-b","text":"Air hujan yang ditampung dalam bejana bersih","isCorrect":false},{"id":"opt-1-c","text":"Air sumur yang mencapai lebih dari dua kullah","isCorrect":false},{"id":"opt-1-d","text":"Air embun di pagi hari","isCorrect":false},{"id":"opt-1-e","text":"Air sungai yang mengalir deras","isCorrect":false}],"correctOptionId":"opt-1-a","points":10,"category":"Thaharah (Bersuci)","difficulty":"mudah"},{"id":"q-2","number":2,"type":"multiple_choice_complex","text":"Manakah di antara pernyataan berikut yang termasuk rukun wudhu yang disepakati menurut madzhab Syafi\'i? (Pilihlah lebih dari satu jawaban yang benar):","options":[{"id":"opt-2-a","text":"Niat ketika membasuh muka","isCorrect":true},{"id":"opt-2-b","text":"Membasuh kedua tangan sampai ke siku","isCorrect":true},{"id":"opt-2-c","text":"Mengusap sebagian kepala","isCorrect":true},{"id":"opt-2-d","text":"Membaca doa setelah wudhu menghadap kiblat","isCorrect":false},{"id":"opt-2-e","text":"Berkumur-kumur dan istinsyaq","isCorrect":false}],"correctOptionIds":["opt-2-a","opt-2-b","opt-2-c"],"points":10,"category":"Thaharah & Wudhu","difficulty":"sedang"},{"id":"q-3","number":3,"type":"matching","text":"Jodohkanlah nama kitab suci samawi berikut dengan nama Nabi yang menerimanya secara tepat:","options":[],"matchingPairs":[{"id":"m-1","leftPrompt":"Kitab Taurat","rightAnswer":"Nabi Musa AS"},{"id":"m-2","leftPrompt":"Kitab Zabur","rightAnswer":"Nabi Daud AS"},{"id":"m-3","leftPrompt":"Kitab Injil","rightAnswer":"Nabi Isa AS"},{"id":"m-4","leftPrompt":"Kitab Suci Al-Qur\'an","rightAnswer":"Nabi Muhammad SAW"}],"points":15,"category":"Akidah & Kitab Samawi","difficulty":"sedang"},{"id":"q-4","number":4,"type":"essay","text":"Jelaskan secara ringkas perbedaan pokok antara Zakat Fitrah dan Zakat Mal, ditinjau dari objek yang dizakati dan batas waktu pengeluarannya!","options":[],"sampleAnswer":"Zakat fitrah adalah zakat jiwa berupa makanan pokok (beras 2,5 kg) yang wajib ditunaikan pada bulan Ramadhan hingga sebelum pelaksanaan shalat Idul Fitri. Sedangkan zakat mal adalah zakat harta benda (seperti emas, perniagaan, hasil bumi) yang dikeluarkan apabila telah mencapai nisab dan telah berlalu masa kepemilikan satu tahun (haul).","keywords":["jiwa","makanan pokok","ramadhan","idul fitri","harta","nisab","haul"],"points":15,"category":"Zakat & Muamalah","difficulty":"sedang"},{"id":"q-5","number":5,"type":"multiple_choice","text":"Berapakah takaran Zakat Fitrah per jiwa berupa beras/makanan pokok yang wajib dibayarkan sebelum shalat Idul Fitri dilaksanakan?","options":[{"id":"opt-5-a","text":"1 sha\' (setara 2,5 kg atau 3,5 liter beras)","isCorrect":true},{"id":"opt-5-b","text":"2 sha\' (setara 5 kg beras)","isCorrect":false},{"id":"opt-5-c","text":"Setengah sha\' (setara 1,5 kg beras)","isCorrect":false},{"id":"opt-5-d","text":"3 sha\' (setara 7 liter beras)","isCorrect":false},{"id":"opt-5-e","text":"Terserah keikhlasan muzakki tanpa batasan","isCorrect":false}],"correctOptionId":"opt-5-a","points":10,"category":"Zakat & Muamalah","difficulty":"mudah"},{"id":"q-6","number":6,"type":"multiple_choice","text":"Hukum melaksanakan ibadah puasa pada hari Raya Idul Fitri (1 Syawal), Idul Adha (10 Dzulhijjah), dan hari Tasyrik (11, 12, 13 Dzulhijjah) adalah...","options":[{"id":"opt-6-a","text":"Haram mutlak","isCorrect":true},{"id":"opt-6-b","text":"Makruh tanzih","isCorrect":false},{"id":"opt-6-c","text":"Mubah jika berniat puasa sunnah","isCorrect":false},{"id":"opt-6-d","text":"Sunnah muakkadah","isCorrect":false},{"id":"opt-6-e","text":"Fardhu kifayah","isCorrect":false}],"correctOptionId":"opt-6-a","points":10,"category":"Shiyam (Puasa)","difficulty":"mudah"},{"id":"q-7","number":7,"type":"multiple_choice","text":"Rukun haji yang membedakannya secara pokok dengan ibadah umrah karena hanya dilakukan pada ibadah haji adalah...","options":[{"id":"opt-7-a","text":"Wukuf di Padang Arafah","isCorrect":true},{"id":"opt-7-b","text":"Thawaf mengelilingi Ka\'bah 7 kali","isCorrect":false},{"id":"opt-7-c","text":"Sa\'i antara Shafa dan Marwah","isCorrect":false},{"id":"opt-7-d","text":"Tahallul (mencukur rambut)","isCorrect":false},{"id":"opt-7-e","text":"Niat ihram dari miqat","isCorrect":false}],"correctOptionId":"opt-7-a","points":10,"category":"Haji & Umrah","difficulty":"sedang"},{"id":"q-8","number":8,"type":"multiple_choice","text":"Dalam ketentuan kurban (udhiyah), seekor sapi atau unta secara syar\'i sah diperuntukkan atas nama patungan maksimal sebanyak...","options":[{"id":"opt-8-a","text":"7 orang shohibul qurban","isCorrect":true},{"id":"opt-8-b","text":"5 orang shohibul qurban","isCorrect":false},{"id":"opt-8-c","text":"10 orang shohibul qurban","isCorrect":false},{"id":"opt-8-d","text":"1 orang saja","isCorrect":false},{"id":"opt-8-e","text":"3 orang shohibul qurban","isCorrect":false}],"correctOptionId":"opt-8-a","points":10,"category":"Qurban & Aqiqah","difficulty":"sedang"},{"id":"q-9","number":9,"type":"multiple_choice","text":"Hak memilih bagi pihak penjual dan pembeli untuk meneruskan atau membatalkan akad jual beli selama masih berada di tempat transaksi disebut...","options":[{"id":"opt-9-a","text":"Khiyar Majlis","isCorrect":true},{"id":"opt-9-b","text":"Khiyar Syarath","isCorrect":false},{"id":"opt-9-c","text":"Khiyar Aibi","isCorrect":false},{"id":"opt-9-d","text":"Khiyar Ru\'yah","isCorrect":false},{"id":"opt-9-e","text":"Riba Nasi\'ah","isCorrect":false}],"correctOptionId":"opt-9-a","points":10,"category":"Fiqih Muamalah","difficulty":"sukar"},{"id":"q-10","number":10,"type":"multiple_choice","text":"Bangkai hewan pada umumnya haram dikonsumsi umat Islam, KECUALI dua jenis bangkai yang dinyatakan suci dan halal oleh Rasulullah SAW, yaitu bangkai...","options":[{"id":"opt-10-a","text":"Ikan dan Belalang","isCorrect":true},{"id":"opt-10-b","text":"Ayam dan Bebek","isCorrect":false},{"id":"opt-10-c","text":"Kambing dan Unta","isCorrect":false},{"id":"opt-10-d","text":"Burung Puyuh dan Kelinci","isCorrect":false},{"id":"opt-10-e","text":"Kepiting dan Belut","isCorrect":false}],"correctOptionId":"opt-10-a","points":10,"category":"Makanan & Minuman Halal","difficulty":"mudah"}]'),
('exm-002', 'AM-ARAB-MTS-2026', 'Asesmen Madrasah (AM): Bahasa Arab Terpadu MTs', 'Bahasa Arab MTs', '2026/2027', 'Genap', 60, 75, 6, 'cls-7a,cls-7b,cls-8a,cls-8b,cls-9a', 1, 1, 3, 'active', 'ARB456', 'usr-teacher-2', 'Ust. Ridwan Kamil, S.Pd', 'guru2', '2026-10-20T07:30:00Z', '2026-10-20T09:00:00Z', '2026-10-20', '07:30', '09:00', '[{"id":"q-ar-1","number":1,"type":"multiple_choice","text":"Arti kata \'مَدْرَسَةٌ\' (Madrasatun) dalam bahasa Indonesia yang tepat adalah...","options":[{"id":"opt-ar1-a","text":"Sekolah / Madrasah tempat belajar","isCorrect":true},{"id":"opt-ar1-b","text":"Perpustakaan tempat membaca","isCorrect":false},{"id":"opt-ar1-c","text":"Kantor kepala madrasah","isCorrect":false},{"id":"opt-ar1-d","text":"Masjid tempat shalat","isCorrect":false}],"correctOptionId":"opt-ar1-a","points":15,"category":"Mufradat (Kosakata)","difficulty":"mudah"},{"id":"q-ar-2","number":2,"type":"multiple_choice_complex","text":"Manakah di antara kata berikut yang termasuk Isim Mutsanna (kata benda yang menunjukkan dua orang/benda)? (Pilihlah lebih dari satu jawaban yang benar):","options":[{"id":"opt-ar2-a","text":"كِتَابَانِ (Dua buku)","isCorrect":true},{"id":"opt-ar2-b","text":"قَلَمَانِ (Dua pena)","isCorrect":true},{"id":"opt-ar2-c","text":"مُسْلِمُوْنَ (Orang-orang muslim)","isCorrect":false},{"id":"opt-ar2-d","text":"طَالِبٌ (Seorang siswa)","isCorrect":false}],"correctOptionIds":["opt-ar2-a","opt-ar2-b"],"points":15,"category":"Qawaid (Tata Bahasa)","difficulty":"sedang"},{"id":"q-ar-3","number":3,"type":"matching","text":"Jodohkan kata ganti (Dhomir Munfashil) berikut dengan artinya dalam bahasa Indonesia secara tepat:","options":[],"matchingPairs":[{"id":"m-ar-1","leftPrompt":"هُوَ (Huwa)","rightAnswer":"Dia (Laki-laki tunggal)"},{"id":"m-ar-2","leftPrompt":"هِيَ (Hiya)","rightAnswer":"Dia (Perempuan tunggal)"},{"id":"m-ar-3","leftPrompt":"أَنْتَ (Anta)","rightAnswer":"Kamu (Laki-laki tunggal)"},{"id":"m-ar-4","leftPrompt":"أَنَا (Ana)","rightAnswer":"Saya / Aku"}],"points":20,"category":"Qawaid (Dhomir)","difficulty":"sedang"},{"id":"q-ar-4","number":4,"type":"multiple_choice","text":"Bentuk Fi\'il Mudhari\' (kata kerja masa kini/akan datang) dari kata dasar \'كَتَبَ\' (telah menulis) untuk dhomir \'هُوَ\' adalah...","options":[{"id":"opt-ar4-a","text":"يَكْتُبُ (Yaktubu)","isCorrect":true},{"id":"opt-ar4-b","text":"تَكْتُبُ (Taktubu)","isCorrect":false},{"id":"opt-ar4-c","text":"أَكْتُبُ (Aktubu)","isCorrect":false},{"id":"opt-ar4-d","text":"نَكْتُبُ (Naktubu)","isCorrect":false}],"correctOptionId":"opt-ar4-a","points":15,"category":"Tasrif Fi\'il","difficulty":"sedang"},{"id":"q-ar-5","number":5,"type":"multiple_choice","text":"Terjemahan bahasa Indonesia yang tepat dari kalimat \'أَنَا أَتَعَلَّمُ اللُّغَةَ الْعَرَبِيَّةَ فِي الْمَدْرَسَةِ\' adalah...","options":[{"id":"opt-ar5-a","text":"Saya belajar bahasa Arab di madrasah","isCorrect":true},{"id":"opt-ar5-b","text":"Kami mengajar bahasa Arab di rumah","isCorrect":false},{"id":"opt-ar5-c","text":"Dia membaca buku bahasa Arab di kelas","isCorrect":false},{"id":"opt-ar5-d","text":"Kamu menulis pelajaran fikih di sekolah","isCorrect":false}],"correctOptionId":"opt-ar5-a","points":15,"category":"Tarjamah","difficulty":"mudah"},{"id":"q-ar-6","number":6,"type":"essay","text":"Jelaskan secara ringkas perbedaan pokok antara Jumlah Ismiyyah (kalimat yang diawali isim/kata benda) dan Jumlah Fi\'liyyah (kalimat yang diawali fi\'il/kata kerja), serta berikan masing-masing 1 contoh kalimat!","options":[],"sampleAnswer":"Jumlah Ismiyyah adalah susunan kalimat yang diawali dengan isim (Mubtada\' dan Khabar), contoh: مُحَمَّدٌ طَالِبٌ نَشِيْطٌ. Sedangkan Jumlah Fi\'liyyah adalah kalimat yang diawali dengan fi\'il (kata kerja) yang diikuti fail (pelaku), contoh: ذَهَبَ أَحْمَدُ إِلَى الْمَدْرَسَةِ.","keywords":["mubtada","khabar","isim","fiil","fail"],"points":20,"category":"Struktur Kalimat","difficulty":"sedang"}]'),
('exm-003', 'AM-QURDIS-MTS-2026', 'Asesmen Madrasah (AM): Al-Qur\'an Hadits MTs', 'Al-Qur\'an Hadits MTs', '2026/2027', 'Genap', 45, 75, 5, 'cls-7a,cls-7b,cls-8a,cls-8b,cls-9a', 1, 1, 3, 'active', 'QRD123', 'usr-teacher-3', 'Dra. Hj. Nurul Hidayah, M.Pd', 'guru3', '2026-10-21T07:30:00Z', '2026-10-21T09:00:00Z', '2026-10-21', '07:30', '09:00', '[{"id":"q-qd-1","number":1,"type":"multiple_choice","text":"Hukum bacaan tajwid apabila Nun Sukun (نْ) atau Tanwin bertemu dengan huruf Ba\' (ب) adalah...","options":[{"id":"opt-qd1-a","text":"Iqlab (mengubah bunyi nun menjadi mim disertai dengung)","isCorrect":true},{"id":"opt-qd1-b","text":"Izhar Halqi (membaca jelas)","isCorrect":false},{"id":"opt-qd1-c","text":"Idgham Bighunnah (memasukkan dengan dengung)","isCorrect":false},{"id":"opt-qd1-d","text":"Ikhfa\' Haqiqi (menyamarkan)","isCorrect":false}],"correctOptionId":"opt-qd1-a","points":20,"category":"Hukum Nun Sukun","difficulty":"mudah"},{"id":"q-qd-2","number":2,"type":"multiple_choice","text":"Hukum bacaan Qalqalah Kubra (pantulan besar) terjadi apabila salah satu huruf qalqalah berharakat hidup namun dibaca sukun karena...","options":[{"id":"opt-qd2-a","text":"Berada di akhir kata karena waqaf (berhenti)","isCorrect":true},{"id":"opt-qd2-b","text":"Berada di tengah-tengah kata berharakat sukun asli","isCorrect":false},{"id":"opt-qd2-c","text":"Bertemu dengan huruf bertasydid di awal ayat","isCorrect":false},{"id":"opt-qd2-d","text":"Didahului oleh huruf mad thabi\'i","isCorrect":false}],"correctOptionId":"opt-qd2-a","points":20,"category":"Ilmu Tajwid","difficulty":"sedang"},{"id":"q-qd-3","number":3,"type":"matching","text":"Jodohkan nama-nama surah pendek berikut dengan arti nama surahnya secara tepat:","options":[],"matchingPairs":[{"id":"m-qd-1","leftPrompt":"QS. Al-Falaq","rightAnswer":"Waktu Subuh"},{"id":"m-qd-2","leftPrompt":"QS. An-Nas","rightAnswer":"Manusia"},{"id":"m-qd-3","leftPrompt":"QS. Al-Ikhlas","rightAnswer":"Kemurnian Keesaan Allah"},{"id":"m-qd-4","leftPrompt":"QS. Al-Kautsar","rightAnswer":"Nikmat yang Berlimpah"}],"points":20,"category":"Ulumul Qur\'an","difficulty":"sedang"},{"id":"q-qd-4","number":4,"type":"multiple_choice","text":"Lanjutan lafadz hadits tentang kebersihan: \'الطُّهُورُ شَطْرُ ...\' yang diriwayatkan oleh Imam Muslim adalah...","options":[{"id":"opt-qd4-a","text":"الْإِيمَانِ (Al-Imaan)","isCorrect":true},{"id":"opt-qd4-b","text":"الصَّلَاةِ (Ash-Shalah)","isCorrect":false},{"id":"opt-qd4-c","text":"الْإِسْلَامِ (Al-Islam)","isCorrect":false},{"id":"opt-qd4-d","text":"الْإِحْسَانِ (Al-Ihsan)","isCorrect":false}],"correctOptionId":"opt-qd4-a","points":20,"category":"Hadits Keutamaan Thaharah","difficulty":"mudah"},{"id":"q-qd-5","number":5,"type":"essay","text":"Sebutkan 5 huruf hijaiyah yang termasuk dalam hukum bacaan Qalqalah (terangkum dalam frasa Quthbu Jadin)!","options":[],"sampleAnswer":"Lima huruf Qalqalah adalah: Qaf (ق), Tha\' (ط), Ba\' (ب), Jim (ج), dan Dal (د).","keywords":["qaf","tha","ba","jim","dal"],"points":20,"category":"Tajwid Qalqalah","difficulty":"mudah"}]');

